import { jsx as _jsx } from "react/jsx-runtime";
import { describe, it, expect } from "vitest";
import { screen, render } from "@testing-library/react";
import { Illustration } from "../Illustration";
describe("Rapid7 Illustration", () => {
    it("Should render the illustration if illustration name is valid", () => {
        render(_jsx(Illustration, { illustrationName: "Celebrate" }));
        expect(screen.getByTestId("Celebrate")).toBeInTheDocument();
    });
    it("Should display the illustration if illustration name is valid", () => {
        // @ts-expect-error
        render(_jsx(Illustration, { illustrationName: "INVALID" }));
        expect(document.querySelector("svg")).not.toBeInTheDocument();
    });
});
